#!/usr/bin/env Rscript

# =============================================================================
# LOPO DeepMicro Embeddings Classification Pipeline (via mikropml)
# =============================================================================
# Description:
# This script takes the low-dimensional latent representations (embeddings) 
# generated by DeepMicro and performs a strict Leave-One-Project-Out (LOPO) 
# classification.
#
# Workflow:
# 1. Data Loading: Ingests headerless DeepMicro embeddings and matches them 
#    strictly by row-order to stacked Train/Test clinical labels.
# 2. Preprocessing: Applies mikropml standard transformations to the latent 
#    space, scaling features and removing zero-variance dimensions.
# 3. Model Training: Trains GLMNET, RF, and SVM exclusively on the Train 
#    project using mikropml's `groups` parameter.
# 4. Evaluation: Evaluates purely on the unseen Test project embeddings.
# =============================================================================

# Setup
library(ggplot2)
library(tidyverse)
library(mikropml)
library(doFuture)
library(caret)
library(optparse)
library(data.table)

registerDoFuture()
plan(multisession, workers = 4)
options(doFuture.rng.onMisuse = "ignore")

# Dynamically set width to match your terminal window
options(width = as.numeric(system("tput cols", intern = TRUE)))

################################################# 
################# DATA LOADING ##################
#################################################

option_list = list(
  make_option(c("--embeddings"), type="character", default=NULL, help="Path to DeepMicro embeddings CSV"),
  make_option(c("--train_labels"), type="character", default=NULL, help="Path to train label CSV"),
  make_option(c("--test_labels"), type="character", default=NULL, help="Path to test label CSV"),
  make_option(c("--output_dir"), type="character", default=NULL, help="Output directory")
)

opt_parser = OptionParser(option_list=option_list)
opt = parse_args(opt_parser)

if (any(sapply(list(opt$embeddings, opt$train_labels, opt$test_labels, opt$output_dir), is.null))) {
  print_help(opt_parser)
  stop("Critical Error: Missing required arguments.", call.=FALSE)
}

if (!dir.exists(opt$output_dir)) dir.create(opt$output_dir, recursive = TRUE)

cat("=== LOPO DEEPMICRO PIPELINE INITIALIZED ===\n")

# 1. Load Embeddings
embeds <- read_csv(opt$embeddings, col_names = FALSE, show_col_types = FALSE)
colnames(embeds) <- paste0("dim_", 1:ncol(embeds))

# 2. Load and Stack Labels (Must match the bind_rows order from 01_align_for_deepmicro.R)
train_labels <- read_csv(opt$train_labels, show_col_types = FALSE)
test_labels <- read_csv(opt$test_labels, show_col_types = FALSE)

combined_labels <- bind_rows(train_labels, test_labels)

if(nrow(embeds) != nrow(combined_labels)) {
  stop("Critical Error: Row count of embeddings does not match combined row count of labels.")
}

# 3. Bind Labels to Embeddings and Attach Rownames
merged_data <- bind_cols(embeds, dx = combined_labels$Label)
merged_data$dx <- factor(ifelse(merged_data$dx == 1, "IBD", "Healthy"), levels = c("Healthy", "IBD"))
merged_data <- merged_data |> select(dx, everything()) |> as.data.frame()

# Crucial: Add Sample Names so downstream outputs are identifiable, not just row indices
rownames(merged_data) <- combined_labels$Sample_Name

#################################################
################# PREPROCESSING #################
#################################################

# Capture the original sample names before mikropml strips them
original_sample_names <- rownames(merged_data)

print("Preprocessing latent embeddings...")
mikropml_input_preproc <- preprocess_data(
  dataset = merged_data,
  outcome_colname = "dx",
  method = c("center", "scale", "zv"), 
  collapse_corr_feats = FALSE 
)

combined_transformed <- mikropml_input_preproc$dat_transformed

# Re-attach the sample names to the transformed dataset
rownames(combined_transformed) <- original_sample_names


#################################################
################ RUNNING MODELS #################
#################################################

# Define LOPO Partitions
# Tag the first N rows as "Train", and the rest as "Test" based on label file lengths
n_train_samples <- nrow(train_labels)
group_vector <- rep(c("Train", "Test"), times = c(n_train_samples, nrow(test_labels)))

model_results <- list()

print(paste("Initiating Training on", n_train_samples, "samples using run_ml partition mapping..."))

print("Training GLMNET baseline...")
model_results$GLMNET <- run_ml(
  dataset = combined_transformed,
  method = "glmnet",
  outcome_colname = "dx",
  groups = group_vector,
  group_partitions = list(train = c("Train"), test = c("Test")),
  seed = 23102004,
  kfold = 5,
  cv_times = 10
)

# Random Forest conditionally based on training size
if (n_train_samples > 100) {
  print("Training sample size > 100 detected. Training Random Forest...")
  model_results$RF <- run_ml(
    dataset = combined_transformed,
    method = "rf",
    outcome_colname = "dx",
    groups = group_vector,
    group_partitions = list(train = c("Train"), test = c("Test")),
    seed = 23102004,
    kfold = 5,
    cv_times = 10
  )
} else {
  print("Training sample size <= 100. Skipping Random Forest.")
}

print("Training Radial SVM...")
model_results$SVM <- run_ml(
  dataset = combined_transformed,
  method = "svmRadial",
  outcome_colname = "dx",
  groups = group_vector,
  group_partitions = list(train = c("Train"), test = c("Test")),
  seed = 23102004,
  kfold = 5,
  cv_times = 10
)

################################################# 
############### GENERATING RESULTS ##############
#################################################

print("Saving output files...")

# 1. Create Organized Subdirectories
out_dirs <- list(
  preds = file.path(opt$output_dir, "predictions"),
  roc = file.path(opt$output_dir, "roc_curves"),
  metrics = file.path(opt$output_dir, "performance_metrics")
)
invisible(lapply(out_dirs, function(d) if(!dir.exists(d)) dir.create(d, recursive = TRUE)))

# 2. Iterate through trained models to save predictions and ROCs
for (model_name in names(model_results)) {
  print(paste("Processing outputs for:", model_name))
  current_res <- model_results[[model_name]]
  
  # A. ROC Curve Generation
  sens_dat <- calc_model_sensspec(
    trained_model = current_res$trained_model,
    test_data = current_res$test_data,
    outcome_colname = "dx"
  )
  
  p_roc <- ggplot(sens_dat, aes(x = specificity, y = sensitivity)) +
    geom_line(color = "#0072B2", linewidth = 1) +
    geom_abline(intercept = 1, slope = 1, linetype = "dashed", color = "grey50") +
    coord_equal() +
    scale_x_reverse(expand = c(0, 0), limits = c(1.01, -0.01)) +
    scale_y_continuous(expand = c(0, 0), limits = c(-0.01, 1.01)) +
    labs(x = "Specificity", y = "Sensitivity", title = paste("ROC Curve:", model_name)) +
    theme_bw() + theme(plot.title = element_text(face="bold"))
    
  ggsave(p_roc, filename = file.path(out_dirs$roc, paste0("ROC_", model_name, ".png")), width = 6, height = 4)
  
  # B. Prediction Table (Probabilities & Classes)
  probs <- predict(current_res$trained_model, newdata = current_res$test_data, type = "prob")
  preds <- predict(current_res$trained_model, newdata = current_res$test_data)
  
  pred_table <- data.table(
    SampleID = rownames(current_res$test_data),
    Actual = current_res$test_data$dx,
    Predicted = preds
  )
  pred_table <- cbind(pred_table, probs)
  fwrite(pred_table, file.path(out_dirs$preds, paste0("Predictions_", model_name, ".csv")))
  
  # C. Confusion Matrix Output
  cm <- confusionMatrix(data = preds, reference = current_res$test_data$dx)
  capture.output(print(cm), file = file.path(out_dirs$preds, paste0("ConfusionMatrix_", model_name, ".txt")))
}

# 3. Global Performance Summary & Advanced Plotting
perf_list <- lapply(names(model_results), function(m) {
  df <- model_results[[m]]$performance
  df$Model <- m
  return(df)
})
all_perf <- do.call(rbind, perf_list)
fwrite(all_perf, file.path(out_dirs$metrics, "All_Models_Performance.csv"))

# Build Cross-Validation Distribution Plot 
p_cv <- ggplot(all_perf, aes(x = Model, y = cv_metric_AUC, fill = Model)) +
  geom_boxplot(alpha = 0.7, outlier.shape = NA) +
  geom_jitter(width = 0.2, alpha = 0.5, size = 1) +
  theme_bw() +
  labs(
    title = "Cross-Validation AUROC Stability",
    subtitle = "Distribution of AUC across repeated CV folds",
    y = "Cross-Validated AUC",
    x = "Algorithm"
  ) +
  theme(legend.position = "none", plot.title = element_text(face="bold"))

ggsave(p_cv, filename = file.path(out_dirs$metrics, "CV_AUC_Distribution.png"), width = 7, height = 5)

print("Pipeline execution completed successfully.")